    "De zaak van de week is gesloten, {0}. Deel het resultaat, dan weet de rest van het bureau het ook.": "हफ़्ते का केस बंद हुआ, {0}। नतीजा शेयर करें, ताकि थाने में बाक़ी सबको भी पता चले।",
    "Uitstekend speurwerk, {0}. Geen hint, geen fout. Zo hoort het.": "शानदार जासूसी, {0}। न कोई संकेत, न कोई ग़लती। ऐसा ही होना चाहिए।",
    "Vlekkeloos, {0}. Ik had het zelf niet beter gekund.": "बेदाग़ काम, {0}। मैं ख़ुद भी इससे बेहतर नहीं कर पाता।",
