    "Goed gezien, {0}. Eén foute gok, maar je hebt hem.": "अच्छी नज़र, {0}। एक ग़लत अंदाज़ा, पर मुजरिम पकड़ में आ गया।",
    "In één keer goed, {0}. Probeer het de volgende keer eens zonder hint.": "पहली बार में सही, {0}। अगली बार बिना संकेत के आज़माएँ।",
    "Opgelost, {0}. Hints zijn er om te gebruiken, maar kijk of je ze de volgende keer kunt missen.": "सुलझ गया, {0}। संकेत इस्तेमाल करने के लिए ही हैं, पर देखिए, शायद अगली बार उनके बिना काम चल जाए।",
    "De zaak is rond, {0}. Lees de verklaringen twee keer, dan heb je de hints niet nodig.": "केस बंद, {0}। बयान दो बार पढ़ें, तो संकेतों की ज़रूरत नहीं पड़ेगी।",
    "Rekruut": "रंगरूट",
    "Sleep {0} van het bord af.{1}{2}": "{0} को बोर्ड से बाहर खींचें।{1}{2}",
    " Lees de verklaring hierboven nog eens en probeer een vakje dat erbij past.": " ऊपर वाला बयान फिर से पढ़ें और ऐसा ख़ाना आज़माएँ जो उससे मेल खाए।",
    "Haal de verdachte weg en kijk welke vakjes die aanwijzing wél toelaat.": "संदिग्ध को हटाएँ और देखें कि वह सुराग किन ख़ानों की इजाज़त देता है।",
    "Precies één persoon bevond zich in die kamer.": "उस कमरे में ठीक एक व्यक्ति था।",
