    "Het archief loopt niet weg. Vandaag ligt “{0}” klaar, als je zin hebt.": "आर्काइव कहीं नहीं जा रहा। आज “{0}” तैयार है, अगर मन हो।",
    "Een rustige dag op het bureau. “{0}” wacht geduldig op een frisse blik.": "दफ़्तर में एक शांत दिन। केस “{0}” धीरज से एक ताज़ा नज़र का इंतज़ार कर रहा है।",
    "Geen haast. Als het uitkomt: “{0}” ligt bovenop de stapel.": "कोई जल्दी नहीं। जब सुविधा हो: “{0}” ढेर में सबसे ऊपर है।",
    "Ik heb je dossierkast netjes bijgehouden. Bovenop vandaag: “{0}”.": "मैंने आपकी फ़ाइलों की अलमारी सँभालकर रखी है। आज सबसे ऊपर: “{0}”।",
