    "{0} dagen op rij. Eén zaak vanavond en het worden er {1}.": "लगातार {0} दिन। आज रात एक केस, और ये {1} हो जाएँगे।",
    "Nog een kort verhoor voor het slapengaan? “{0}” houdt je streak van {1} dagen heel.": "सोने से पहले एक छोटी-सी पूछताछ? केस “{0}” आपकी {1} दिन की स्ट्रीक को बनाए रखेगा।",
    "🔥 {0} dagen. Het vuur brandt nog; één zaak houdt het aan.": "🔥 {0} दिन। आग अभी जल रही है; एक केस उसे जलाए रखेगा।",
    "Om middernacht sluit het dossier van vandaag. Tijd genoeg voor “{0}” en dag {1} van je streak.": "आधी रात को आज की फ़ाइल बंद हो जाएगी। “{0}” और आपकी स्ट्रीक के {1}वें दिन के लिए काफ़ी समय है।",
    "Rustig avondwerk: “{0}”. Daarmee komt je streak op {1} dagen.": "शाम का इत्मीनान वाला काम: “{0}”। इससे आपकी स्ट्रीक {1} दिन की हो जाएगी।",
