    "Een uur later, zelfde dossier: “{0}”. Je streak van {1} dagen wacht.": "एक घंटे बाद, वही फ़ाइल: “{0}”। आपकी {1} दिन की स्ट्रीक इंतज़ार में है।",
    "Hier ben ik weer. Eén zaak, en je streak gaat naar {0} dagen.": "मैं फिर हाज़िर हूँ। एक केस, और आपकी स्ट्रीक {0} दिन की हो जाएगी।",
