        "room": "{s} {room.in} ही कहीं है। वहाँ का कोई भी ख़ाली ख़ाना चलेगा।",
        "not-room": "{s} {room.obl} को छोड़कर कहीं भी {s|m:हो सकता|f:हो सकती} है।",
        "room-pos.hoek": "{s} {room.obl} के एक कोने में है। कोना यानी ऐसा ख़ाना जो उसकी दो दीवारों को छूता है।",
